      uutNotForThisProcessResult.PassFail = false;
      uutNotForThisProcessResult.Status = ts.truthy(uutNotForThisProcessResult.PassFail) ? 'Passed' : 'Failed';
      run.record(uutNotForThisProcessResult.Status);
      break body;
    }
  } finally {
    // Failed Point
  }

  return run.status;
}

